examples.template:
Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    photos.indices.forEach { i ->
        MonarchButton(
            text = "$buttonLabel ${i + 1}",
            onClick = {
                index = i
                viewing = true
            },
        )
    }
}
if (viewing) {
    MonarchLightbox(
        items = photos,
        selectedIndex = index,
        onSelectedIndexChange = { index = it },
        onDismissRequest = { viewing = false },
    )
}

