MonarchLightbox(
    items = listOf(
        MonarchLightboxItem(image = samplePainter(), alt = "Team photo", caption = "Lisbon"),
        // The app's own player, for example a Media3 PlayerSurface with its controls.
        MonarchLightboxItem(image = null, alt = "Product demo", video = { MonarchText(text = "Video player") }),
    ),
    selectedIndex = index,
    onSelectedIndexChange = { index = it },
    onDismissRequest = {},
    looping = true,
    onShare = {
        val send = Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT, "https://example.com/photos/$it")
        context.startActivity(Intent.createChooser(send, null))
    },
)
